from torch.utils.cpp_extension import load_inline

# CUDA kernel for matrix multiplication with warp-level optimization
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 64
#define WARPS_PER_BLOCK 4
#define WARP_SIZE 32
#define THREADS_PER_BLOCK (WARP_SIZE * WARPS_PER_BLOCK)

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles (double buffered)
    __shared__ float tileA[2][TILE_SIZE][TILE_SIZE];
    __shared__ float tileB[2][TILE_SIZE][TILE_SIZE];

    int warp_id = threadIdx.x / WARP_SIZE;
    int lane_id = threadIdx.x % WARP_SIZE;

    int warp_row = warp_id / (TILE_SIZE / WARP_SIZE);
    int warp_col = warp_id % (TILE_SIZE / WARP_SIZE);

    int row = blockIdx.y * TILE_SIZE + warp_row * WARP_SIZE + lane_id;
    int col = blockIdx.x * TILE_SIZE + warp_col * WARP_SIZE + lane_id;

    float sum = 0.0f;

    // Double buffering variables
    int buffer_idx = 0;
    int next_buffer = 1;

    // Loop over tiles
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int tile = 0; tile < num_tiles; tile++) {
        // Pre-fetch next tile while computing current
        int next_tile = tile + 1;

        // Load tile from A
        int load_row = row;
        int load_col = tile * TILE_SIZE + lane_id;

        if (load_row < N && load_col < N) {
            tileA[buffer_idx][warp_row * WARP_SIZE + lane_id][lane_id] = A[load_row * N + load_col];
        } else {
            tileA[buffer_idx][warp_row * WARP_SIZE + lane_id][lane_id] = 0.0f;
        }

        // Load tile from B
        int load_row_b = tile * TILE_SIZE + warp_row * WARP_SIZE + lane_id;
        int load_col_b = col;

        if (load_row_b < N && load_col_b < N) {
            tileB[buffer_idx][lane_id][warp_col * WARP_SIZE + lane_id] = B[load_row_b * N + load_col_b];
        } else {
            tileB[buffer_idx][lane_id][warp_col * WARP_SIZE + lane_id] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum for current tile
        if (tile > 0) {
            for (int k = 0; k < TILE_SIZE; k++) {
                sum += tileA[next_buffer][threadIdx.y][k] * tileB[next_buffer][k][threadIdx.x];
            }
        }

        __syncthreads();

        // Swap buffers
        int temp = buffer_idx;
        buffer_idx = next_buffer;
        next_buffer = temp;
    }

    // Compute last tile
    for (int k = 0; k < TILE_SIZE; k++) {
        sum += tileA[buffer_idx][threadIdx.y][k] * tileB[buffer_idx][k][threadIdx.x];
    }

    // Store result
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

